// Config plugin for local release builds (android/ is generated by `expo prebuild`; never edit it by hand).
//
// - Release signing: reads TASTORIA_UPLOAD_STORE_FILE / _KEY_ALIAS / _STORE_PASSWORD / _KEY_PASSWORD from
//   Gradle properties or environment variables (e.g. `set -a; . ~/.config/tastoria/keystore.env; set +a`).
//   If they are absent, the release build falls back to the debug keystore so `assembleRelease` still works.
//   No secrets live in the repo.
// - ABIs limited to arm64-v8a + armeabi-v7a; Gradle heap/workers sized for this build.
const { withAppBuildGradle, withGradleProperties } = require('expo/config-plugins');

const MARKER = '// tastoria-release-signing';

const SIGNING_BLOCK = `
        release { ${MARKER}
            def tProp = { String k -> findProperty(k) ?: System.getenv(k) }
            if (tProp('TASTORIA_UPLOAD_STORE_FILE')) {
                storeFile file(tProp('TASTORIA_UPLOAD_STORE_FILE'))
                storePassword tProp('TASTORIA_UPLOAD_STORE_PASSWORD')
                keyAlias tProp('TASTORIA_UPLOAD_KEY_ALIAS')
                keyPassword tProp('TASTORIA_UPLOAD_KEY_PASSWORD')
            }
        }`;

function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes(MARKER)) return cfg;

    // 1. add a release signingConfig after the debug one
    const debugCfg = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
    if (!debugCfg.test(src)) throw new Error('with-android-release: signingConfigs.debug not found in app/build.gradle');
    src = src.replace(debugCfg, `$1${SIGNING_BLOCK}`);

    // 2. release buildType: use it when configured, else debug
    const releaseType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
    if (!releaseType.test(src)) throw new Error('with-android-release: release buildType signingConfig not found');
    src = src.replace(
      releaseType,
      `$1signingConfig signingConfigs.release.storeFile ? signingConfigs.release : signingConfigs.debug`,
    );

    cfg.modResults.contents = src;
    return cfg;
  });
}

function withBuildProperties(config) {
  return withGradleProperties(config, (cfg) => {
    const set = (key, value) => {
      const item = cfg.modResults.find((p) => p.type === 'property' && p.key === key);
      if (item) item.value = value;
      else cfg.modResults.push({ type: 'property', key, value });
    };
    set('reactNativeArchitectures', 'arm64-v8a,armeabi-v7a');
    set('org.gradle.jvmargs', '-Xmx6g -XX:MaxMetaspaceSize=1g');
    set('org.gradle.workers.max', '8');
    return cfg;
  });
}

module.exports = (config) => withBuildProperties(withReleaseSigning(config));
